import re
import json

def load_all():
    d = os.environ['RLM_SESSION_DIR']
    session_name = os.path.basename(d)
    t_path = d + f'/../../sessions/{session_name}.jsonl'
    t = open(t_path).read()
    grids = {}

    # Parse demo 1
    d1_match = re.search(r'Demo pair 1 input.*?(?=\nDemo pair 1 output|\Z)', t, re.DOTALL)
    if d1_match:
        text = d1_match.group(0)
        lines = text.split('\n')
        grid = []
        for line in lines:
            if line.strip() and line[0].isdigit():
                grid.append([int(x) for x in line.split()])
            elif len(grid) > 0 and grid[-1] and (line.strip() == '' or not line[0].isdigit()):
                continue
        grids['demo1_input'] = grid

    d2_match = re.search(r'Demo pair 2 input.*?(?=\nDemo pair 2 output|\Z)', t, re.DOTALL)
    if d2_match:
        text = d2_match.group(0)
        lines = text.split('\n')
        grid = []
        for line in lines:
            if line.strip() and line[0].isdigit():
                grid.append([int(x) for x in line.split()])
            elif len(grid) > 0 and grid[-1] and (line.strip() == '' or not line[0].isdigit()):
                continue
        grids['demo2_input'] = grid

    return grids

grids = load_all()
print("Demo 1 input shape:", len(grids.get('demo1_input', [[]])), "x", len(grids.get('demo1_input', [[]])[0]) if grids.get('demo1_input') else 0)
print("Demo 1 output - looking for:")
d1_out_match = re.search(r'Demo pair 1 output.*?(?=\nSame instance|\Z)', t, re.DOTALL)
if d1_out_match:
    text = d1_out_match.group(0)
    lines = text.split('\n')
    grid = []
    for line in lines:
        if line.strip() and line[0].isdigit():
            grid.append([int(x) for x in line.split()])
    print("Demo 1 output:", grid)

d2_out_match = re.search(r'Demo pair 2 output.*?(?=\nSame instance|\Z)', t, re.DOTALL)
if d2_out_match:
    text = d2_out_match.group(0)
    lines = text.split('\n')
    grid = []
    for line in lines:
        if line.strip() and line[0].isdigit():
            grid.append([int(x) for x in line.split()])
    print("Demo 2 output:", grid)

